<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { ChevronRight } from '@lucide/svelte'; import { cn } from '../../utils.js'; import type { SchemaProperty } from './context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'class'>, SchemaProperty { depth?: number; class?: string; children?: Snippet<[SchemaProperty, number]>; } let { name, type, required = false, description, properties, items, depth = 0, class: className = '', children, ...rest }: Props = $props(); const property = $derived({ name, type, required, description, properties, items });</script>
{#snippet tree(node: SchemaProperty, level: number)}
  {@const nested = Boolean(node.properties?.length || node.items)}
  {#if nested}<details open={level < 2} class="svadmin-ai-schema-part__property-node"><summary style={`--schema-level: ${level}`}><ChevronRight size={13} aria-hidden="true" /><code>{node.name}</code><span>{node.type}</span>{#if node.required}<strong>required</strong>{/if}</summary>{#if node.description}<p style={`--schema-level: ${level}`}>{node.description}</p>{/if}<div>{#each node.properties ?? [] as child (child.name)}{@render tree(child, level + 1)}{/each}{#if node.items}{@render tree({ ...node.items, name: `${node.name}[]` }, level + 1)}{/if}</div></details>{:else}<div class="svadmin-ai-schema-part__property-leaf" style={`--schema-level: ${level}`}><span aria-hidden="true"></span><code>{node.name}</code><span>{node.type}</span>{#if node.required}<strong>required</strong>{/if}{#if node.description}<p>{node.description}</p>{/if}</div>{/if}
{/snippet}
<div {...rest} class={cn('svadmin-ai-schema-part__property', className)} data-slot="schema-display-property">{#if children}{@render children(property, depth)}{:else}{@render tree(property, depth)}{/if}</div>
<style>.svadmin-ai-schema-part__property :global(summary), .svadmin-ai-schema-part__property-leaf { display: grid; grid-template-columns: 1rem auto auto auto minmax(0, 1fr); align-items: center; gap: .4rem; padding: .6rem .75rem .6rem calc(.75rem + var(--schema-level) * 1rem); list-style: none; font-size: .74rem; }.svadmin-ai-schema-part__property :global(summary) { cursor: pointer; }.svadmin-ai-schema-part__property :global(summary::-webkit-details-marker) { display: none; }.svadmin-ai-schema-part__property :global(details[open] > summary svg) { transform: rotate(90deg); }.svadmin-ai-schema-part__property code { font-size: .74rem; }.svadmin-ai-schema-part__property :global(summary > span), .svadmin-ai-schema-part__property-leaf > span:nth-of-type(2) { padding: .06rem .3rem; border: 1px solid var(--border, currentColor); border-radius: .25rem; color: var(--muted-foreground, currentColor); font-size: .64rem; }.svadmin-ai-schema-part__property strong { color: var(--destructive, currentColor); font-size: .64rem; }.svadmin-ai-schema-part__property p { grid-column: 2 / -1; margin: 0; padding: 0 .75rem .55rem calc(1.75rem + var(--schema-level) * 1rem); color: var(--muted-foreground, currentColor); font-size: .7rem; }.svadmin-ai-schema-part__property-leaf p { padding: 0; }.svadmin-ai-schema-part__property-node > div { border-top: 1px solid var(--border, currentColor); }</style>
